    <Dialog open={cancel !== null} onClose={() => !busy && setCancel(null)} title="Cancel unsent email approval"><p>Invalidate this unsent approval. No provider-accepted or uncertain request can be cancelled here.</p><div className="dialog-actions"><Button variant="danger" disabled={busy} onClick={() => action(async () => { await api("/api/workspace/email/deliveries/" + cancel!.id + "/cancel", "POST", { revision: cancel!.revision, confirmation: "CANCEL EMAIL" }); setCancel(null); await refresh(); setMessage("Unsent approval cancelled."); })}>Confirm cancellation</Button><Button variant="secondary" disabled={busy} onClick={() => setCancel(null)}>Keep approval</Button></div></Dialog>
